/* 风景印 scene library: one little inked picture per kind of place, drawn in two inks (c = main line ink, a = accent ink).
   Scene box: x 24–196, sky from y 30, ground line at y 146 (the name band covers 150–174).
   sceneFor(name, city) picks the picture: an exact landmark first, then keywords, then the guide's type, then the region. */
import { GUIDES } from "./guides.js";

const P = "#fbf6ea";
const r1 = n => Math.round(n * 10) / 10;
/* ---------- primitives ---------- */
export const roof = (cx, y, w, c) => `<path d="M${cx - w} ${y}Q${cx} ${y - w * .45} ${cx + w} ${y}L${cx + w * .78} ${y - w * .22}Q${cx} ${y - w * .8} ${cx - w * .78} ${y - w * .22}Z" fill="${c}"/>`;
const flatRoof = (cx, y, w, c) => `<path d="M${cx - w} ${y}L${cx - w * .7} ${y - w * .35}H${cx + w * .7}L${cx + w} ${y}Z" fill="${c}"/>`;
const waves = (y0, n, c, w = 1.6, x0 = 20) => Array.from({ length: n }, (_, i) => `<path d="M${x0} ${y0 + i * 7}${Array.from({ length: 12 }, () => `q7.5 ${i % 2 ? 3.5 : -3.5} 15 0`).join("")}" stroke="${c}" stroke-width="${w}" fill="none"/>`).join("");
const tree = (x, y, r, c, a) => `<path d="M${x} ${y}v${r * 1.2}" stroke="${c}" stroke-width="2"/><circle cx="${x}" cy="${y - r * .2}" r="${r}" fill="${a}" fill-opacity=".85"/><circle cx="${x}" cy="${y - r * .2}" r="${r}" fill="none" stroke="${c}" stroke-width="1.6"/>`;
const pine = (x, y, s, c, a) => `<path d="M${x} ${y}v${-s * 1.4}" stroke="${c}" stroke-width="1.8"/><path d="M${x - s} ${y - s * .5}L${x} ${y - s * 2.2}L${x + s} ${y - s * .5}Z" fill="${a}" fill-opacity=".8" stroke="${c}" stroke-width="1.4"/>`;
const palm = (x, y, s, c, a) => `<path d="M${x} ${y}q${s * .3} ${-s * 1.2} ${s * .9} ${-s * 2.2}" stroke="${c}" stroke-width="2.4" fill="none"/>${[[-1.4, .2], [-.8, -.6], [.2, -.9], [1.1, -.4], [1.3, .5]].map(([dx, dy]) => `<path d="M${x + s * .9} ${y - s * 2.2}q${dx * s * .5} ${dy * s * .5 - s * .3} ${dx * s} ${dy * s}" stroke="${a}" stroke-width="3" fill="none" stroke-linecap="round"/>`).join("")}`;
const birds = (x, y, c) => `<path d="M${x} ${y}q4-4 8 0q4-4 8 0M${x + 22} ${y - 8}q3-3 6 0q3-3 6 0" stroke="${c}" stroke-width="1.4" fill="none"/>`;
export const cloud = (x, y, c) => `<path d="M${x} ${y}h30M${x + 8} ${y - 6}h26M${x - 6} ${y + 6}h18" stroke="${c}" stroke-width="1.6" stroke-linecap="round"/>`;
const ground = c => `<path d="M20 146H200" stroke="${c}" stroke-width="2"/>`;
const boat = (x, y, s, c, a) => `<path d="M${x - s} ${y}h${s * 2}l${-s * .3} ${s * .35}h${-s * 1.4}z" fill="${c}"/><path d="M${x} ${y}v${-s * 1.3}l${s * .8} ${s * 1.1}z" fill="${a}"/>`;
const lantern = (x, y, a, c) => `<path d="M${x} ${y - 7}v-3" stroke="${c}" stroke-width="1"/><ellipse cx="${x}" cy="${y}" rx="4.5" ry="6" fill="${a}"/><path d="M${x - 2.5} ${y + 6}h5" stroke="${c}" stroke-width="1.2"/>`;
const win = (x, y, w, h, c, n = 2, gap = 4) => Array.from({ length: n }, (_, i) => `<rect x="${x + i * (w + gap)}" y="${y}" width="${w}" height="${h}" fill="none" stroke="${c}" stroke-width="1.2"/>`).join("");
const box = (x, y, w, h, c, a, op = .14) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${a || c}" fill-opacity="${op}" stroke="${c}" stroke-width="2"/>`;
const mtn = (pts, c, a, op = .18) => `<path d="M${pts}Z" fill="${a || c}" fill-opacity="${op}" stroke="${c}" stroke-width="2" stroke-linejoin="round"/>`;
const snowcap = (x, y, s, c) => `<path d="M${x - s} ${y + s * .8}l${s * .4} -${s * .2}l${s * .3} ${s * .3}l${s * .3} -${s * .5}L${x} ${y}Z" fill="${P}" stroke="${c}" stroke-width="1.2"/>`;
const stall = (x, w, c, a, y = 146) => `<rect x="${x}" y="${y - 26}" width="${w}" height="26" fill="${c}" fill-opacity=".12" stroke="${c}" stroke-width="1.8"/><path d="M${x - 3} ${y - 26}l3 -12h${w}l3 12z" fill="${a}"/>${Array.from({ length: Math.floor(w / 8) }, (_, i) => `<path d="M${x + 4 + i * 8} ${y - 38}l-1 12" stroke="${P}" stroke-width="2.6"/>`).join("")}<path d="M${x + 4} ${y - 14}h${w - 8}" stroke="${c}" stroke-width="1.4"/>${[0, 1, 2].map(k => `<circle cx="${x + 8 + k * (w - 16) / 2}" cy="${y - 17}" r="2.6" fill="${a}"/>`).join("")}`;
const dome = (cx, y, r, c, a) => `<path d="M${cx - r} ${y}a${r} ${r} 0 0 1 ${r * 2} 0Z" fill="${a}" stroke="${c}" stroke-width="1.8"/><path d="M${cx} ${y - r}v-8" stroke="${c}" stroke-width="1.6"/><path d="M${cx - 3} ${y - r - 8}a3 3 0 1 0 6 0" fill="none" stroke="${c}" stroke-width="1.4"/>`;
const onion = (cx, y, r, c, a) => `<path d="M${cx - r} ${y}q0 ${-r * 1.2} ${r} ${-r * 1.9}q${r} ${r * .7} ${r} ${r * 1.9}z" fill="${a}" stroke="${c}" stroke-width="1.6"/><path d="M${cx} ${y - r * 1.9}v-7M${cx - 3} ${y - r * 1.9 - 4}h6" stroke="${c}" stroke-width="1.4"/>`;
const spire = (cx, y, w, h, c, a) => `<path d="M${cx - w} ${y}L${cx} ${y - h}L${cx + w} ${y}Z" fill="${a}" stroke="${c}" stroke-width="1.6"/><path d="M${cx} ${y - h}v-6M${cx - 3} ${y - h - 3}h6" stroke="${c}" stroke-width="1.4"/>`;
const stars = a => `${[[40, 44], [70, 36], [132, 40], [176, 52], [96, 50], [160, 34]].map(([x, y]) => `<path d="M${x} ${y - 3}v6M${x - 3} ${y}h6" stroke="${a}" stroke-width="1.3"/>`).join("")}`;
const person = (x, y, c, a) => `<circle cx="${x}" cy="${y - 13}" r="2.6" fill="${c}"/><path d="M${x} ${y - 10}v6l-3 4M${x} ${y - 4}l3 4M${x - 3} ${y - 8}h6" stroke="${c}" stroke-width="1.4" fill="none"/>`;
const cablecar = (x, y, c, a) => `<path d="M${x} ${y - 10}v6" stroke="${c}" stroke-width="1.4"/><rect x="${x - 7}" y="${y - 4}" width="14" height="11" rx="2" fill="${a}" stroke="${c}" stroke-width="1.4"/><path d="M${x - 4} ${y}h8" stroke="${P}" stroke-width="2"/>`;
const flag = (x, y, c, a) => `<path d="M${x} ${y}v-40" stroke="${c}" stroke-width="1.8"/><path d="M${x} ${y - 40}h18l-4 6 4 6h-18z" fill="${a}"/>`;

/* ---------- scenes ---------- */
const S = {};
/* bridges */
S.bridge_pontoon = (c, a) => `${waves(128, 3, c)}<path d="M24 110H196" stroke="${c}" stroke-width="3"/>${[40, 150].map(x => `<path d="M${x} 114a15 13 0 0 1 30 0" stroke="${c}" stroke-width="2.2" fill="none"/><path d="M${x} 110v18M${x + 30} 110v18" stroke="${c}" stroke-width="2.4"/>`).join("")}
  ${[82, 96, 110, 124, 138].map(x => `<path d="M${x - 6} 118h12l-2 5h-8z" fill="${c}"/>`).join("")}<path d="M76 116H144" stroke="${c}" stroke-width="1.2" stroke-dasharray="3 2"/>
  ${[54, 165].map(x => `<path d="M${x - 8} 110V99M${x + 8} 110V99" stroke="${c}" stroke-width="1.6"/>${roof(x, 99, 14, a)}${roof(x, 90, 9, c)}`).join("")}${roof(110, 104, 10, c)}`;
S.bridge_stone = (c, a) => `${waves(126, 3, c)}<path d="M20 116H200" stroke="${c}" stroke-width="3.4"/>${Array.from({ length: 9 }, (_, i) => `<path d="M${30 + i * 20} 119l-4 7h8z" fill="${c}"/>`).join("")}${[40, 110, 180].map(x => `<path d="M${x} 116v-12M${x - 4} 104h8" stroke="${c}" stroke-width="1.6"/><path d="M${x - 5} 104q5-8 10 0" fill="${a}"/>`).join("")}${person(90, 116, c, a)}${person(128, 116, c, a)}${birds(60, 62, c)}`;
S.bridge_suspension = (c, a) => `${waves(130, 3, c)}<path d="M20 116H200" stroke="${c}" stroke-width="3"/>${[66, 154].map(x => `<rect x="${x - 4}" y="62" width="8" height="64" fill="${a}" stroke="${c}" stroke-width="1.6"/><path d="M${x - 4} 74h8M${x - 4} 90h8" stroke="${c}" stroke-width="1.2"/>`).join("")}
  <path d="M20 108Q43 72 66 64Q110 100 154 64Q177 72 200 108" stroke="${c}" stroke-width="1.8" fill="none"/>${Array.from({ length: 13 }, (_, i) => { const x = 26 + i * 14; const y = x < 66 ? 108 - (x - 20) * .9 : x < 154 ? 64 + Math.sin((x - 66) / 88 * Math.PI) * 36 : 64 + (x - 154) * .95; return `<path d="M${x} ${r1(y)}V116" stroke="${c}" stroke-width=".8"/>`; }).join("")}`;
S.bridge_canyon = (c, a) => `${mtn("20 146L20 70L52 62L64 118L60 146", c, a, .3)}${mtn("200 146L200 66L168 60L156 118L160 146", c, a, .3)}<path d="M58 84H162" stroke="${c}" stroke-width="3"/><path d="M58 88H162" stroke="${a}" stroke-width="3" stroke-dasharray="6 3"/>${person(96, 84, c, a)}${person(118, 84, c, a)}<path d="M100 88v34" stroke="${c}" stroke-width=".8" stroke-dasharray="2 2"/>${pine(34, 60, 7, c, a)}${pine(186, 58, 7, c, a)}`;
S.bridge_jetty = (c, a) => `${waves(132, 2, c)}<path d="M20 120H200" stroke="${c}" stroke-width="2.4"/>${Array.from({ length: 10 }, (_, i) => `<path d="M${26 + i * 19} 120v14" stroke="${c}" stroke-width="2"/>`).join("")}${[44, 96, 150].map(x => `${box(x - 14, 98, 28, 22, c, a)}${flatRoof(x, 98, 18, a)}`).join("")}${lantern(70, 108, a, c)}${lantern(124, 108, a, c)}${boat(178, 140, 10, c, a)}`;
/* Chinese temples & halls */
S.temple = (c, a) => `<path d="M40 146H180M50 140H170M60 134H160" stroke="${c}" stroke-width="2"/>${box(70, 100, 80, 34, c)}${[80, 96, 124, 140].map(x => `<path d="M${x} 100v34" stroke="${c}" stroke-width="2"/>`).join("")}
  <rect x="102" y="110" width="16" height="24" rx="8" fill="${a}"/>${roof(110, 100, 52, c)}<path d="M72 78q38-12 76 0" stroke="${c}" stroke-width="2" fill="none"/>${roof(110, 78, 34, a)}<path d="M104 62h12M110 56v8" stroke="${c}" stroke-width="2"/>${tree(44, 118, 12, c, a)}${tree(178, 116, 10, c, a)}`;
const pagodaAt = (x, base, tiers, w0, c, a) => Array.from({ length: tiers }, (_, i) => { const w = w0 - i * (w0 / (tiers + 2)), y = base - i * 16; return `<rect x="${r1(x - w * .6)}" y="${y - 12}" width="${r1(w * 1.2)}" height="12" fill="${c}" fill-opacity=".14" stroke="${c}" stroke-width="1.6"/>${roof(x, y - 12, w, i % 2 ? a : c)}`; }).join("") + `<path d="M${x} ${base - tiers * 16 - 4}v-12" stroke="${c}" stroke-width="2"/>`;
S.pagoda = (c, a) => `${ground(c)}${pagodaAt(110, 146, 6, 30, c, a)}${tree(48, 128, 14, c, a)}${tree(172, 130, 11, c, a)}`;
S.twin_pagoda = (c, a) => `${ground(c)}${pagodaAt(52, 146, 5, 20, c, a)}${pagodaAt(168, 146, 5, 20, c, a)}${box(88, 118, 44, 28, c)}${roof(110, 118, 32, a)}<rect x="104" y="126" width="12" height="20" fill="${a}"/>`;
S.three_pagodas = (c, a) => `${mtn("20 110L60 64L96 98L140 58L200 106V146H20Z", c, null, .1)}${ground(c)}${pagodaAt(110, 146, 8, 18, c, a)}${pagodaAt(60, 146, 5, 13, c, a)}${pagodaAt(160, 146, 5, 13, c, a)}`;
S.ancestral_hall = (c, a) => `${ground(c)}${box(46, 106, 128, 40, c)}${roof(110, 106, 70, c)}<path d="M52 92l8-10h100l8 10" stroke="${c}" stroke-width="1.4" fill="none"/>${[0, 1, 2, 3, 4].map(i => `<circle cx="${70 + i * 20}" cy="88" r="3" fill="${a}"/>`).join("")}
  <rect x="98" y="116" width="24" height="30" fill="${a}"/><path d="M110 116v30" stroke="${P}" stroke-width="1.4"/>${[60, 80, 140, 160].map(x => `<path d="M${x} 112h10v14h-10z" fill="none" stroke="${c}" stroke-width="1.2"/><path d="M${x} 119h10M${x + 5} 112v14" stroke="${c}" stroke-width=".8"/>`).join("")}${lantern(88, 124, a, c)}${lantern(132, 124, a, c)}`;
S.mansion = (c, a) => `${ground(c)}${box(30, 108, 160, 38, c)}${[40, 110, 180].map(x => roof(x, 108, 26, x === 110 ? a : c)).join("")}${roof(110, 94, 20, c)}${[44, 62, 150, 168].map(x => `<rect x="${x}" y="118" width="10" height="14" fill="${a}" fill-opacity=".6" stroke="${c}" stroke-width="1.2"/>`).join("")}<rect x="100" y="120" width="20" height="26" fill="${a}"/>${tree(24, 128, 9, c, a)}`;
S.academy = (c, a) => `${mtn("20 120L70 60L120 104L160 72L200 118V146H20Z", c, null, .12)}${ground(c)}${box(62, 114, 96, 32, c)}${roof(110, 114, 56, a)}<rect x="96" y="122" width="28" height="12" fill="${P}" stroke="${c}" stroke-width="1.2"/><path d="M102 128h16" stroke="${c}" stroke-width="1.6"/>${pine(40, 146, 9, c, a)}${pine(182, 146, 8, c, a)}`;
S.bell_tower = (c, a) => `${ground(c)}${box(62, 110, 96, 36, c)}<path d="M96 146v-18a14 14 0 0 1 28 0v18" fill="${a}" stroke="${c}" stroke-width="1.6"/>${box(76, 84, 68, 20, c, a, .2)}${roof(110, 84, 46, c)}${roof(110, 110, 58, c)}${box(88, 64, 44, 14, c)}${roof(110, 64, 32, a)}`;
S.forbidden = (c, a) => `${ground(c)}<path d="M20 146V128H200V146" fill="${a}" fill-opacity=".35" stroke="${c}" stroke-width="2"/>${[70, 98, 122, 150].map(x => `<path d="M${x} 146v-10a6 6 0 0 1 12 0v10" fill="${P}" stroke="${c}" stroke-width="1.2"/>`).join("")}
  ${box(56, 104, 108, 24, c, a, .5)}${roof(110, 104, 66, c)}${roof(110, 88, 48, a)}${roof(40, 124, 18, c)}${roof(180, 124, 18, c)}`;
S.heaven_temple = (c, a) => `${ground(c)}<path d="M50 146h120l-8-8H58z" fill="none" stroke="${c}" stroke-width="1.6"/><path d="M60 138h100l-8-8H68z" fill="none" stroke="${c}" stroke-width="1.6"/>${box(84, 108, 52, 22, c, a, .4)}
  <path d="M68 108q42-18 84 0z" fill="${c}"/>${box(90, 90, 40, 12, c, a, .4)}<path d="M76 90q34-16 68 0z" fill="${c}"/>${box(96, 74, 28, 10, c, a, .4)}<path d="M84 74q26-14 52 0z" fill="${c}"/><circle cx="110" cy="60" r="4" fill="${a}"/>`;
S.great_wall = (c, a) => `${mtn("20 146L20 120L64 88L100 110L150 78L200 106V146Z", c, null, .12)}<path d="M20 124L64 94L100 116L150 84L200 112" stroke="${c}" stroke-width="6" fill="none"/><path d="M20 118L64 88L100 110L150 78L200 106" stroke="${c}" stroke-width="2" stroke-dasharray="4 3" fill="none"/>
  ${[[64, 94], [150, 84]].map(([x, y]) => `${box(x - 11, y - 22, 22, 22, c, a, .6)}${roof(x, y - 22, 14, c)}`).join("")}${birds(90, 56, c)}`;
S.city_gate = (c, a) => `<path d="M24 146V112${Array.from({ length: 12 }, () => `h7v-6h7v6`).join("")}V146" fill="${c}" fill-opacity=".14" stroke="${c}" stroke-width="2"/><path d="M96 146v-22a14 14 0 0 1 28 0v22" fill="${a}" stroke="${c}" stroke-width="2"/>
  ${box(74, 88, 72, 20, c, c, .18)}${roof(110, 88, 48, c)}<rect x="86" y="70" width="48" height="12" fill="none" stroke="${c}" stroke-width="1.8"/>${roof(110, 70, 32, a)}${[34, 60, 160, 186].map(x => `<path d="M${x - 12} 128h24" stroke="${c}" stroke-width="1.2"/>`).join("")}`;
S.old_town_gate = (c, a) => `${ground(c)}${[30, 70, 150].map((x, i) => `${box(x, 104 + i * 4, 36, 42 - i * 4, c, i === 1 ? a : c, .14)}${roof(x + 18, 104 + i * 4, 22, c)}`).join("")}${box(92, 94, 36, 52, c, a, .3)}<path d="M100 146v-20a10 10 0 0 1 20 0v20" fill="${a}" stroke="${c}" stroke-width="1.4"/>${roof(110, 94, 26, a)}${lantern(96, 104, a, c)}${lantern(124, 104, a, c)}`;
S.paifang = (c, a) => `${ground(c)}${[56, 164].map(x => `${box(x - 18, 108, 36, 38, c)}${roof(x, 108, 24, c)}`).join("")}${[84, 136].map(x => `<rect x="${x - 4}" y="84" width="8" height="62" fill="${c}"/>`).join("")}<rect x="80" y="92" width="60" height="12" fill="${a}"/><path d="M92 98h36" stroke="${P}" stroke-width="1.6"/>${roof(110, 84, 40, c)}${roof(110, 72, 26, a)}${lantern(110, 120, a, c)}`;
/* streets */
S.qilou = (c, a) => `${ground(c)}${[[26, 66, 70], [66, 52, 80], [110, 60, 72], [150, 46, 82]].map(([x, top, w], i) => `<rect x="${x}" y="${top}" width="${w * .52}" height="${146 - top}" fill="${i % 2 ? a : c}" fill-opacity="${i % 2 ? .22 : .12}" stroke="${c}" stroke-width="2"/>
  ${[0, 1].map(k => `<rect x="${x + 6 + k * 12}" y="${top + 10}" width="7" height="12" rx="3.5" fill="none" stroke="${c}" stroke-width="1.3"/>`).join("")}<path d="M${x + 4} 146v-14a${w * .22} ${w * .22} 0 0 1 ${w * .44} 0v14" fill="none" stroke="${c}" stroke-width="1.6"/><path d="M${x - 2} ${top}h${w * .56}" stroke="${c}" stroke-width="3"/><path d="M${x + 4} ${top - 6}h${w * .44}v6" fill="none" stroke="${c}" stroke-width="1.2"/>`).join("")}
  <path d="M30 96Q110 112 190 92" stroke="${c}" stroke-width="1" fill="none"/>${[52, 84, 116, 148, 176].map((x, i) => lantern(x, 100 + r1(Math.sin(i) * 3), a, c)).join("")}`;
S.shophouse = (c, a) => `${ground(c)}${[0, 1, 2, 3].map(i => { const x = 26 + i * 42, h = [58, 52, 60, 54][i]; return `${box(x, 146 - h, 40, h, c, i % 2 ? a : c, i % 2 ? .3 : .12)}<path d="M${x - 2} ${146 - h}h44" stroke="${c}" stroke-width="3"/><path d="M${x + 8} ${146 - h - 8}q12-8 24 0v8h-24z" fill="${i % 2 ? c : a}" fill-opacity=".7"/>
  ${win(x + 6, 146 - h + 10, 8, 12, c, 3, 3)}<path d="M${x + 4} 146v-16h32v16" fill="none" stroke="${c}" stroke-width="1.4"/><path d="M${x} ${116}h40" stroke="${c}" stroke-width="1.2" stroke-dasharray="3 2"/>`; }).join("")}${lantern(68, 124, a, c)}${lantern(152, 124, a, c)}`;
S.mural = (c, a) => `${ground(c)}${box(24, 70, 172, 76, c, a, .12)}${win(34, 80, 12, 16, c, 2, 8)}${win(150, 80, 12, 16, c, 2, 8)}<circle cx="86" cy="134" r="10" fill="none" stroke="${c}" stroke-width="2"/><circle cx="124" cy="134" r="10" fill="none" stroke="${c}" stroke-width="2"/><path d="M86 134l14-16h16l8 16M100 118l-4-8" stroke="${c}" stroke-width="2" fill="none"/>
  <circle cx="104" cy="98" r="5" fill="${a}"/><path d="M104 103v10l-6 8M104 110l8 6" stroke="${a}" stroke-width="3" fill="none"/><circle cx="118" cy="104" r="4" fill="${a}"/><path d="M118 108v8" stroke="${a}" stroke-width="3"/>`;
S.hutong = (c, a) => `${ground(c)}${box(24, 110, 70, 36, c)}${box(126, 106, 70, 40, c)}${flatRoof(59, 110, 40, c)}${flatRoof(161, 106, 40, c)}<rect x="46" y="120" width="24" height="26" fill="${a}"/><circle cx="52" cy="132" r="1.6" fill="${P}"/><circle cx="64" cy="132" r="1.6" fill="${P}"/>${lantern(40, 122, a, c)}${lantern(78, 122, a, c)}${tree(112, 112, 16, c, a)}<path d="M150 124h26" stroke="${c}" stroke-width="1.2"/>`;
